target.css:
:root {
  --paper: #fffdf7;
  --ink: #26382d;
  --muted: #6f796d;
  --line: #d9dfd1;
  --sage: #e5eddf;
  --moss: #496044;
  --clay: #b76542;
  --cream: #f4eedf;
}

.tea-card {
  width: 480px;
  box-sizing: border-box;
  padding: 18px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0;
  color: var(--moss);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.09em;
  line-height: 1.2;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0;
  font-size: 23px;
  line-height: 1.1;
}

.status {
  padding: 5px 9px;
  color: var(--moss);
  background: var(--sage);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.session-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 18px;
  padding: 15px 0;
}

.tea-profile {
  padding-right: 18px;
  border-right: 1px solid var(--line);
}

.tea-name {
  margin: 5px 0 6px;
  font-size: 17px;
  font-weight: 700;
  line-height: 1.2;
}

.description {
  margin-bottom: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
}

.session-details h2 {
  margin-bottom: 8px;
  font-size: 14px;
  line-height: 1.2;
}

.details {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px 12px;
  margin: 0;
}

.details div {
  min-width: 0;
}

.details dt {
  margin-bottom: 2px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.2;
}

.details dd {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.25;
}

.note {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 11px;
  background: var(--cream);
  border-radius: 10px;
}

.note span {
  display: grid;
  width: 25px;
  height: 25px;
  flex: 0 0 auto;
  place-items: center;
  color: var(--paper);
  background: var(--clay);
  border-radius: 50%;
  font-size: 11px;
  font-weight: 700;
}

.note p {
  margin: 0;
  color: var(--ink);
  font-size: 12px;
  line-height: 1.35;
}

.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 13px;
}

.footer strong {
  font-size: 12px;
}

button {
  padding: 7px 11px;
  color: var(--paper);
  background: var(--moss);
  border: 0;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 700;
}

